import java.util.*;
import java.io.*;

public class CF998B {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), w = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        int evenCount = 0, oddCount = 0;
        List<Integer> cutDifferences = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            if ((a[i] & 1) == 0) evenCount++;
            else oddCount++;
            if (evenCount == oddCount) {
                cutDifferences.add(Math.abs(a[i] - a[i + 1]));
            }
        }
        int m = cutDifferences.size();
        int[][] dp = new int[m + 1][w + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= w; j++) {
                if (i == 0 || j == 0) dp[i][j] = 0;
            }
        }
        for (int i = 1; i <= m; i++) {
            int val = cutDifferences.get(i - 1);
            for (int j = 1; j <= w; j++) {
                if (val <= j) {
                    dp[i][j] = Math.max(1 + dp[i - 1][j - val], dp[i - 1][j]);
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }
        System.out.println(dp[m][w]);
        sc.close();
    }
}
