#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, w;
    std::cin >> n >> w;
    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    int evenCount = 0, oddCount = 0;
    std::vector<int> cutDifferences;
    for (int i = 0; i < n - 1; i++) {
        if ((a[i] & 1) == 0) {
            evenCount++;
        } else {
            oddCount++;
        }
        if (evenCount == oddCount) {
            cutDifferences.push_back(std::abs(a[i] - a[i + 1]));
        }
    }

    int m = static_cast<int>(cutDifferences.size());
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(w + 1, 0));

    for (int i = 1; i <= m; i++) {
        int val = cutDifferences[i - 1];
        for (int j = 1; j <= w; j++) {
            if (val <= j) {
                dp[i][j] = std::max(1 + dp[i - 1][j - val], dp[i - 1][j]);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    std::cout << dp[m][w] << std::endl;
    return 0;
}

